import {artworks,themes,essentialQuestion} from './artworks.js';
const $=s=>document.querySelector(s), viewport=$('#viewport'),panel=$('#art-panel'),backdrop=$('#backdrop');
$('#essential-question').textContent=essentialQuestion;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let THREE,renderer,scene,camera,clock,groups=[],clickTargets=[],currentTheme=0,selected=-1,transition=null,frame=0,dragging=false,dragStart=null,look={x:0,y:0},lookTarget={x:0,y:0},visible=true,animating=false,raf=0;
const cardButtons=[];
function populatePanel(i){const a=artworks[i];$('#panel-theme').textContent=themes[a.theme].name;$('#panel-title').textContent=a.title;$('#panel-creator').textContent=a.creator;$('#panel-description').textContent=a.description;$('#panel-reflection').textContent=a.reflection;$('#panel-concepts').textContent=a.concepts;$('#panel-connection').textContent=a.connection;}
function openPanel(i){populatePanel(i);panel.classList.add('open');backdrop.classList.add('open');panel.setAttribute('aria-hidden','false');$('#close-panel').focus({preventScroll:true});}
function hidePanel(){panel.classList.remove('open');backdrop.classList.remove('open');panel.setAttribute('aria-hidden','true');}
function setTheme(n){if(animating||selected!==-1)return;currentTheme=(n+3)%3;document.querySelectorAll('.theme-button').forEach((b,i)=>b.classList.toggle('active',i===currentTheme));document.querySelectorAll('.fallback button').forEach((b,i)=>b.hidden=Math.floor(i/3)!==currentTheme);lookTarget={x:0,y:0};}
function focusArtwork(i){if(animating||selected!==-1)return;const a=artworks[i];if(currentTheme!==a.theme)setTheme(a.theme);selected=i;animating=true;transition={kind:'open',start:performance.now(),duration:reduced?10:1400,index:i};}
function closeArtwork(){if(selected<0||animating)return;hidePanel();animating=true;transition={kind:'close',start:performance.now(),duration:reduced?10:950,index:selected};}
$('#close-panel').onclick=closeArtwork;backdrop.onclick=closeArtwork;
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeArtwork();if(selected!==-1||animating)return;if(e.key==='ArrowRight'){e.preventDefault();setTheme(currentTheme+1)}if(e.key==='ArrowLeft'){e.preventDefault();setTheme(currentTheme-1)}});
document.querySelectorAll('.theme-button').forEach((b,i)=>b.onclick=()=>setTheme(i));
$('#next-art').onclick=()=>{if(selected!==-1){closeArtwork();return;}focusArtwork(currentTheme*3+Math.floor(Math.random()*3))};
$('#art-list').onclick=()=>{$('#fallback').classList.toggle('show-list');};
const list=$('#fallback-grid');artworks.forEach((a,i)=>{const b=document.createElement('button');b.textContent=`${String(i+1).padStart(2,'0')} · ${a.title}`;b.onclick=()=>focusArtwork(i);list.appendChild(b);cardButtons.push(b)});
function fallback(message){document.body.classList.add('error');$('#hint').textContent=message||'Explore the museum through the artwork list.';$('#fallback').style.display='block';document.querySelectorAll('.fallback button').forEach((b,i)=>b.hidden=Math.floor(i/3)!==currentTheme);}
function textureLabel(title,index){const c=document.createElement('canvas');c.width=512;c.height=640;const x=c.getContext('2d');const g=x.createLinearGradient(0,0,512,640);g.addColorStop(0,'#1b2c43');g.addColorStop(.55,'#101b2e');g.addColorStop(1,'#070e1d');x.fillStyle=g;x.fillRect(0,0,512,640);x.strokeStyle='#6e8db244';x.lineWidth=2;for(let k=0;k<7;k++){x.beginPath();x.ellipse(256,290,75+k*25,90+k*32,k*.23,0,Math.PI*2);x.stroke()}x.fillStyle='#d9b779';x.font='19px sans-serif';x.textAlign='center';x.fillText('ORIGINAL ARTWORK',256,90);x.font='bold 90px Georgia';x.fillText(String(index+1).padStart(2,'0'),256,332);x.font='20px sans-serif';x.fillStyle='#c3d2e8';x.fillText('YOUR ART GOES HERE',256,540);return new THREE.CanvasTexture(c)}
function makeFrame(a,i){const group=new THREE.Group(),matGold=new THREE.MeshStandardMaterial({color:0xbfa16c,metalness:.82,roughness:.27}),dark=new THREE.MeshStandardMaterial({color:0x0b1220,metalness:.25,roughness:.7});const w=2.1,h=2.65,d=.12;
const back=new THREE.Mesh(new THREE.BoxGeometry(w+.14,h+.14,.12),dark);group.add(back);
for(const [x,y,sx,sy] of [[0,h/2,w+.3,.11],[0,-h/2,w+.3,.11],[-w/2,0,.11,h+.2],[w/2,0,.11,h+.2]]){const edge=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,.19),matGold);edge.position.set(x,y,.09);group.add(edge)}
let texture;if(a.image){const loader=new THREE.TextureLoader();texture=loader.load(a.image,undefined,undefined,()=>{texture.dispose();});texture.colorSpace=THREE.SRGBColorSpace}else texture=textureLabel(a.title,i);
const art=new THREE.Mesh(new THREE.PlaneGeometry(w-.11,h-.11),new THREE.MeshBasicMaterial({map:texture,side:THREE.DoubleSide}));art.position.z=.21;group.add(art);art.userData.index=i;clickTargets.push(art);
const glow=new THREE.Mesh(new THREE.PlaneGeometry(w+1.1,h+1.1),new THREE.MeshBasicMaterial({color:0xd8a85c,transparent:true,opacity:0,depthWrite:false,side:THREE.DoubleSide}));glow.position.z=-.12;group.add(glow);
const label=document.createElement('canvas');label.width=512;label.height=64;const ctx=label.getContext('2d');ctx.fillStyle='#d5c6a7';ctx.font='22px sans-serif';ctx.textAlign='center';ctx.fillText(a.title,256,39);const labelTexture=new THREE.CanvasTexture(label);const name=new THREE.Mesh(new THREE.PlaneGeometry(2.5,.32),new THREE.MeshBasicMaterial({map:labelTexture,transparent:true,depthWrite:false}));name.position.y=-h/2-.37;group.add(name);
const local=i%3;group.position.set((local-1)*3.15,Math.sin(i*2.3)*.42,-Math.abs(local-1)*1.25);group.rotation.y=(local-1)*-.11;scene.add(group);return {group,art,glow,name,origin:group.position.clone(),baseRot:group.rotation.y,texture,labelTexture};}
function smooth(t){return t*t*(3-2*t)}
function lerp(a,b,t){return a+(b-a)*t}
async function init(){try{THREE=await import('https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js');if(!window.WebGLRenderingContext)throw Error('WebGL unavailable');scene=new THREE.Scene();scene.background=new THREE.Color(0x080e1c);scene.fog=new THREE.FogExp2(0x080e1c,.022);camera=new THREE.PerspectiveCamera(48,1,.1,100);camera.position.set(0,0,11.5);renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.7));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;viewport.appendChild(renderer.domElement);scene.add(new THREE.AmbientLight(0x9ab7e9,1.2));const key=new THREE.PointLight(0xf1c985,60,25);key.position.set(-4,5,6);scene.add(key);const blue=new THREE.PointLight(0x3b78ff,45,23);blue.position.set(5,-3,1);scene.add(blue);
const starCount=220,points=new Float32Array(starCount*3);for(let i=0;i<starCount;i++){points[i*3]=(Math.random()-.5)*45;points[i*3+1]=(Math.random()-.5)*26;points[i*3+2]=-5-Math.random()*28}const stars=new THREE.Points(new THREE.BufferGeometry(),new THREE.PointsMaterial({color:0x9ab8ee,size:.055,transparent:true,opacity:.52,sizeAttenuation:true}));stars.geometry.setAttribute('position',new THREE.BufferAttribute(points,3));scene.add(stars);
groups=artworks.map(makeFrame);clock=new THREE.Clock();resize();new ResizeObserver(resize).observe(viewport);
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();viewport.addEventListener('pointerdown',e=>{dragStart={x:e.clientX,y:e.clientY,t:performance.now()};dragging=true;});viewport.addEventListener('pointermove',e=>{if(dragging&&dragStart){lookTarget.x=Math.max(-.35,Math.min(.35,lookTarget.x+(e.clientX-dragStart.x)*.0009));lookTarget.y=Math.max(-.22,Math.min(.22,lookTarget.y+(e.clientY-dragStart.y)*.0007));dragStart.moved=(dragStart.moved||0)+Math.abs(e.movementX||0)+Math.abs(e.movementY||0);dragStart.x=e.clientX;dragStart.y=e.clientY}else if(!reduced){lookTarget.x=((e.clientX/innerWidth)-.5)*.17;lookTarget.y=((e.clientY/innerHeight)-.5)*.12;}});
viewport.addEventListener('pointerup',e=>{const was=dragStart;dragging=false;dragStart=null;if(!was||was.moved>12||selected!==-1||animating)return;const rect=viewport.getBoundingClientRect();pointer.set(((e.clientX-rect.left)/rect.width)*2-1,-((e.clientY-rect.top)/rect.height)*2+1);raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects(clickTargets,false).find(h=>h.object.visible);if(hit)focusArtwork(hit.object.userData.index)});viewport.addEventListener('pointercancel',()=>{dragging=false;dragStart=null});
const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible&&!raf)animate();});observer.observe(viewport);document.addEventListener('visibilitychange',()=>{visible=!document.hidden;if(visible&&!raf)animate()});animate();
}catch(e){console.warn('Museum fallback:',e);fallback('3D is unavailable on this device. Choose an artwork below.')}}
function resize(){if(!renderer)return;const w=viewport.clientWidth,h=viewport.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.fov=w<700?63:48;camera.updateProjectionMatrix();}
function animate(){if(!renderer||!visible||document.hidden){raf=0;return;}raf=requestAnimationFrame(animate);const t=clock.getElapsedTime(),now=performance.now();look.x=lerp(look.x,lookTarget.x,.035);look.y=lerp(look.y,lookTarget.y,.035);
const destination=currentTheme*3;groups.forEach((g,i)=>{const local=i%3,active=Math.floor(i/3)===currentTheme;g.group.visible=active||i===selected;if(!g.group.visible)return;g.group.position.x=lerp(g.group.position.x,g.origin.x,.06);g.group.position.y=lerp(g.group.position.y,g.origin.y+(reduced?0:Math.sin(t*.7+i*1.4)*.11),.06);g.group.position.z=lerp(g.group.position.z,g.origin.z,.06);g.group.rotation.y=lerp(g.group.rotation.y,g.baseRot+(reduced?0:Math.sin(t*.5+i)*.035),.05);g.art.position.set(0,0,.21);g.art.rotation.y=0;g.glow.material.opacity=lerp(g.glow.material.opacity,0,.09);g.art.material.opacity=1;});
let cameraZ=innerWidth<700?15:11.5,cameraX=look.x*3,cameraY=-look.y*2;
if(selected>=0&&transition){const p=Math.min(1,(now-transition.start)/transition.duration),v=smooth(p),g=groups[selected];if(transition.kind==='open'){cameraZ=lerp(cameraZ,8.2,v);cameraX=lerp(cameraX,g.origin.x*.45,v);g.group.position.z=lerp(g.origin.z,2.3,v);g.group.position.x=lerp(g.origin.x,-1.5,v);g.group.rotation.y=lerp(g.baseRot,-.13,v);g.art.position.x=lerp(0,-.65,v);g.art.position.z=lerp(.21,1.15,v);g.art.rotation.y=lerp(0,-.3,v);g.glow.material.opacity=.28*v;if(p>=1){transition=null;animating=false;openPanel(selected)}}else{const inv=1-v;cameraZ=lerp(cameraZ,8.2,inv);cameraX=lerp(cameraX,g.origin.x*.45,inv);g.group.position.z=lerp(g.origin.z,2.3,inv);g.group.position.x=lerp(g.origin.x,-1.5,inv);g.group.rotation.y=lerp(g.baseRot,-.13,inv);g.art.position.x=-.65*inv;g.art.position.z=.21+.94*inv;g.art.rotation.y=-.3*inv;g.glow.material.opacity=.28*inv;if(p>=1){selected=-1;transition=null;animating=false}}}
else if(selected>=0){const g=groups[selected];cameraZ=8.2;cameraX=g.origin.x*.45;g.group.position.set(-1.5,g.origin.y,2.3);g.group.rotation.y=-.13;g.art.position.set(-.65,0,1.15);g.art.rotation.y=-.3;g.glow.material.opacity=.28;}
camera.position.x=lerp(camera.position.x,cameraX,.1);camera.position.y=lerp(camera.position.y,cameraY,.1);camera.position.z=lerp(camera.position.z,cameraZ,.1);camera.lookAt(0,0,0);renderer.render(scene,camera);}
// Provide readable, keyboard-accessible list even when WebGL works.
$('#fallback').classList.add('list-available');setTheme(0);init();
